  clearTimeout(verificationTimer);isAdmin=admin;verifiedUntil=Number(expires)||0;verificationRequired=required||(verifiedUntil>0&&verifiedUntil*1000<=Date.now());trigger.hidden=!admin;sideLabel.hidden=sideEntry.hidden=!admin;
