 async function request(path,body){const expected=revision;assertCurrent(expected);const response=await accountFetch('/api/admin/membership/'+path,{...(body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),cache:'no-store',signal:AbortSignal.timeout(20000)});assertCurrent(expected);const data=await response.json();assertCurrent(expected);if(response.status===403&&data.code==='admin_verification_required'){window.dispatchEvent(new CustomEvent('jt:admin-verification-required'));throw staleRequest()}if(!response.ok)throw Error(data.error||'操作未完成，请重试');return data}
 async function action(callback){if(busy||!dialog.open||!allowed())return;const expected=revision;busy=true;dialog.querySelectorAll('button[type=submit]').forEach(button=>button.disabled=true);status.textContent='处理中…';try{await callback()}catch(error){if(expected===revision&&allowed()&&error.name!=='AbortError')status.textContent=error.name==='TimeoutError'?'请求暂未完成，请刷新列表确认结果。':error.message}finally{if(expected===revision){busy=false;dialog.querySelectorAll('button[type=submit]').forEach(button=>button.disabled=false)}}}
